<?php require __DIR__.'/../../bootstrap/app.php';role_required('admin');$db=Database::get();
$R=['admin','staff','customer','technical'];$me=(int)user()['id'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';$id=(int)($_POST['id']??0);
 if($a==='create'){$n=trim((string)($_POST['name']??''));$em=trim((string)($_POST['email']??''));$ro=$_POST['role']??'';
  if(mb_strlen($n)<2||!filter_var($em,FILTER_VALIDATE_EMAIL)||!in_array($ro,$R,true))notice('Enter a name, a valid email and a role.');
  else{$pw=temp_password();try{$db->prepare("INSERT INTO users(name,email,password_hash,role_id,status) VALUES(?,?,?,(SELECT id FROM roles WHERE name=?),'active')")->execute([$n,$em,password_hash($pw,PASSWORD_DEFAULT),$ro]);audit('create user','user',(int)$db->lastInsertId(),['role'=>$ro]);notice("Account created for $em as $ro. Temporary password (shown once): $pw");}catch(PDOException $x){notice('That email is already registered.');}}}
 elseif($id&&$id!==$me){
  if($a==='role'&&in_array($_POST['role']??'',$R,true)){$db->prepare("UPDATE users SET role_id=(SELECT id FROM roles WHERE name=?) WHERE id=?")->execute([$_POST['role'],$id]);audit('change role','user',$id,['role'=>$_POST['role']]);notice('Role updated. It applies at the next login.');}
  if($a==='status'&&in_array($_POST['status']??'',['active','suspended','disabled'],true)){$db->prepare("UPDATE users SET status=? WHERE id=?")->execute([$_POST['status'],$id]);audit('user '.$_POST['status'],'user',$id);notice('Status updated.');}
  if($a==='reset'){$pw=temp_password();$db->prepare("UPDATE users SET password_hash=? WHERE id=?")->execute([password_hash($pw,PASSWORD_DEFAULT),$id]);audit('reset password','user',$id);notice('New temporary password (shown once): '.$pw);}}
 elseif($id===$me)notice('You cannot change your own role or status here.');
 go('admin/users.php');}
$rows=$db->query("SELECT u.id,u.name,u.email,u.status,r.name role,u.created_at FROM users u JOIN roles r ON r.id=u.role_id ORDER BY u.id DESC LIMIT 200")->fetchAll();
$title='Users';require __DIR__.'/../../app/Views/header.php';?><section class="section"><div class="container"><div class="dash"><?php require __DIR__.'/../../app/Views/admin_nav.php';?><div><h1>Users</h1>
<form method="post" class="cardx mb-4 row g-2"><?=csrf_field()?><input type="hidden" name="action" value="create"><div class="col-md-3"><input class="form-control" name="name" placeholder="Full name" required></div><div class="col-md-3"><input class="form-control" type="email" name="email" placeholder="Email" required></div><div class="col-md-3"><select class="form-select" name="role"><?php foreach($R as $x):?><option><?=e($x)?></option><?php endforeach;?></select></div><div class="col-md-3"><button class="btn btn-dark w-100">Create account</button></div></form>
<div class="table-responsive"><table class="table"><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['role'])?></td><td><?=e($r['status'])?></td><td><?php if((int)$r['id']!==$me):?>
<form method="post" class="d-flex gap-1 flex-wrap"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$r['id']?>"><select name="role" class="form-select form-select-sm w-auto"><?php foreach($R as $x):?><option <?=$x===$r['role']?'selected':''?>><?=e($x)?></option><?php endforeach;?></select><button name="action" value="role" class="btn btn-sm btn-outline-dark">Set role</button><button name="action" value="status" onclick="this.form.insertAdjacentHTML('beforeend','<input type=hidden name=status value=<?=$r['status']==='active'?'suspended':'active'?>>')" class="btn btn-sm btn-outline-dark"><?=$r['status']==='active'?'Suspend':'Activate'?></button><button name="action" value="reset" class="btn btn-sm btn-outline-danger" onclick="return confirm('Reset this password?')">Reset password</button></form><?php else:?>You<?php endif;?></td></tr><?php endforeach;?></table></div></div></div></div></section><?php require __DIR__.'/../../app/Views/footer.php';?>
